def capped_simplex_project(v, target):
    v = np.asarray(v, dtype=float)
    lo = float(np.min(v) - 1.0)
    hi = float(np.max(v))
    for _ in range(90):
        mid = 0.5 * (lo + hi)
        s = float(np.sum(np.clip(v - mid, 0.0, 1.0)))
        if s > target:
            lo = mid
        else:
            hi = mid
    x = np.clip(v - 0.5 * (lo + hi), 0.0, 1.0)
    r = target - float(np.sum(x))
    if abs(r) > 1e-11:
        if r > 0:
            ids = np.where(x < 1.0 - 1e-12)[0]
            for i in ids:
                a = min(r, 1.0 - x[i])
                x[i] += a
                r -= a
                if r <= 1e-12:
                    break
        else:
            r = -r
            ids = np.where(x > 1e-12)[0]
            for i in ids:
                a = min(r, x[i])
                x[i] -= a
                r -= a
                if r <= 1e-12:
                    break
    return x

def lag_pairs(n, lag):
