    if key in _CACHE:
        return _CACHE[key]
    d = int(lag) - (n - 1)
    if d >= 0:
        a = np.arange(d, n, dtype=np.int32)
        b = a - d
    else:
        b = np.arange(-d, n, dtype=np.int32)
