def epi_obj(z, lags):
    return float(z[-1])

def epi_jac(z, lags):
    g = np.zeros_like(z)
    g[-1] = 1.0
    return g

def epi_mass(z, target):
    return float(np.sum(z[:-1]) - target)

def epi_mass_jac(z, target):
    g = np.zeros_like(z)
    g[:-1] = 1.0
    return g

def epi_ineq(z, lags):
    return z[-1] - lag_values(z[:-1], lags)

def epi_ineq_jac(z, lags):
    h = z[:-1]
    jac = np.zeros((len(lags), h.size + 1), dtype=float)
    for r, lag in enumerate(lags):
        jac[r, :-1] = -lag_grad(h, int(lag))
        jac[r, -1] = 1.0
    return jac

def resample_to_n(h, n):
    old_n = h.size
    x_old = (np.arange(old_n, dtype=float) + 0.5) / old_n
    x_new = (np.arange(n, dtype=float) + 0.5) / n
    y = np.interp(x_new, x_old, h)
    return capped_simplex_project(y, n / 2.0)

def smooth_resample_to_n(h, n, sigma):
    y = gaussian_filter1d(np.asarray(h, dtype=float), sigma=sigma, mode="nearest")
    return resample_to_n(y, n)

def quantile_push(h, strength):
    x = np.asarray(h, dtype=float)
    y = x + strength * (x - 0.5) * (1.0 - 4.0 * (x - 0.5) * (x - 0.5))
    return capped_simplex_project(y, x.size / 2.0)

def make_multiscale_perturb(h, rng, amp, sigma1, sigma2):
    z = rng.normal(0.0, amp, h.size)
    z = gaussian_filter1d(z, sigma=sigma1, mode="nearest")
    if sigma2 > 0:
        z -= 0.55 * gaussian_filter1d(z, sigma=sigma2, mode="nearest")
    z -= float(np.mean(z))
    return capped_simplex_project(h + z, h.size / 2.0)

def slp_direction(h, lags, trust):
    n = h.size
    vals = lag_values(h, lags)
    grads = np.zeros((len(lags), n), dtype=float)
    for r, lag in enumerate(lags):
        grads[r] = lag_grad(h, int(lag))

    c = np.zeros(n + 1, dtype=float)
    c[-1] = 1.0
    aub = np.zeros((len(lags), n + 1), dtype=float)
    aub[:, :n] = grads
    aub[:, n] = -1.0
    bub = -vals

    aeq = np.zeros((1, n + 1), dtype=float)
    aeq[0, :n] = 1.0

    bounds = []
    for i in range(n):
        bounds.append((max(-trust, -float(h[i])), min(trust, 1.0 - float(h[i]))))
    bounds.append((0.0, 1.0))

    res = linprog(
        c, A_ub=aub, b_ub=bub, A_eq=aeq, b_eq=np.array([0.0]),
        bounds=bounds, method="highs",
        options={"presolve": True, "dual_feasibility_tolerance": 1e-9,
                 "primal_feasibility_tolerance": 1e-9}
    )
    if res.success and hasattr(res, "x"):
        return res.x[:n]
    return np.zeros(n, dtype=float)

def line_search(h, d):
    best = h
    best_c = erdos_c5_value(h)
    for a in (1.75, 1.35, 1.0, 0.74, 0.52, 0.36, 0.24, 0.155, 0.095, 0.056, 0.031, 0.016):
        cand = capped_simplex_project(h + a * d, h.size / 2.0)
        c = erdos_c5_value(cand)
        if c < best_c - 1e-14:
            best, best_c = cand, c
    return best, best_c

def slp_pass(h, end_time, seed, trust0, count0, margin0):
    best = capped_simplex_project(h, h.size / 2.0)
    best_c = erdos_c5_value(best)
    trust = trust0
    rng = np.random.default_rng(int(seed))
    for it in range(100):
        if time.time() >= end_time:
            break
        count = min(count0 + 5 * it, 2 * best.size - 1)
        margin = margin0 / (1.0 + 0.015 * it)
        lags = active_lags(best, count, margin)
        d = slp_direction(best, lags, trust)
        cand, c = line_search(best, d)
        if c < best_c - 2e-14:
            best, best_c = cand, c
            trust = min(0.06, trust * 1.18)
        else:
            trust *= 0.55
            if trust < 1.7e-4:
                cand = make_multiscale_perturb(best, rng, 2.2e-4, 3 + (it % 8), 14 + (it % 17))
                c = erdos_c5_value(cand)
                if c < best_c:
                    best, best_c = cand, c
                trust = 0.004
    return best, best_c

def coordinate_descent_active(h, end_time, seed):
    rng = np.random.default_rng(int(seed))
    best = capped_simplex_project(h, h.size / 2.0)
    best_c = erdos_c5_value(best)
    n = best.size

    for it in range(260):
        if time.time() >= end_time:
            break

        y = corr_full(best)
        m = float(np.max(y))
        lags = np.where(y >= m - 0.0010 / (1.0 + 0.01 * it))[0]
        if lags.size < 180:
            lags = np.argpartition(y, -180)[-180:]

        tau = 2.5e-5
        g = np.zeros(n, dtype=float)
        sw = 0.0
        for lag in lags:
            w = math.exp(max(-70.0, (float(y[int(lag)]) - m) / tau))
            g += w * lag_grad(best, int(lag))
            sw += w
        if sw > 0:
            g /= sw

        add_pool = np.where(best < 1.0 - 1e-11)[0]
        sub_pool = np.where(best > 1e-11)[0]
        if add_pool.size == 0 or sub_pool.size == 0:
            break

        na = min(48, add_pool.size)
        ns = min(48, sub_pool.size)
        adds = add_pool[np.argpartition(g[add_pool], na - 1)[:na]]
        subs = sub_pool[np.argpartition(-g[sub_pool], ns - 1)[:ns]]

        improved = False
        for _ in range(96):
            ia = int(adds[rng.integers(0, adds.size)])
            ib = int(subs[rng.integers(0, subs.size)])
            if ia == ib:
                continue
            maxeps = min(1.0 - best[ia], best[ib])
            if maxeps <= 1e-13:
                continue
            for frac in (1.0, 0.72, 0.52, 0.35, 0.22, 0.135, 0.08, 0.045, 0.024):
                cand = best.copy()
                eps = maxeps * frac
                cand[ia] += eps
                cand[ib] -= eps
                c = erdos_c5_value(cand)
                if c < best_c - 8e-15:
                    best, best_c = cand, c
                    improved = True
                    break
            if improved:
                break

        if not improved and it % 7 == 6:
            cand = make_multiscale_perturb(best, rng, 1.2e-4, 2 + (it % 7), 11 + (it % 13))
            c = erdos_c5_value(cand)
            if c < best_c:
                best, best_c = cand, c

    return best, best_c

def slsqp_soft_polish(h, end_time):
    n = h.size
    target = n / 2.0
    best = capped_simplex_project(h, target)
    best_c = erdos_c5_value(best)
    bounds = [(0.0, 1.0)] * n
    cons = {"type": "eq", "fun": mass_fun, "jac": mass_jac, "args": (target,)}
    schedule = (
        (360, 8.0e-5, 0.00110, 80),
        (560, 2.2e-5, 0.00065, 95),
        (760, 6.0e-6, 0.00036, 105),
    )
    for count, tau, margin, maxiter in schedule:
        if time.time() >= end_time:
            break
        lags = active_lags(best, min(count, 2 * n - 1), margin)
        res = minimize(
            soft_fun, best, args=(lags, tau), method="SLSQP", jac=soft_jac,
            bounds=bounds, constraints=(cons,),
            options={"maxiter": maxiter, "ftol": 5e-15, "disp": False},
        )
        if hasattr(res, "x"):
            cand = capped_simplex_project(res.x, target)
            c = erdos_c5_value(cand)
            if c < best_c - 1e-14:
                best, best_c = cand, c
            else:
                break
    return best, best_c

def epigraph_polish(h, end_time):
    n = h.size
    target = n / 2.0
    best = capped_simplex_project(h, target)
    best_c = erdos_c5_value(best)
    schedule = (
        (240, 0.00020, 70),
        (420, 0.00011, 90),
        (700, 0.000060, 105),
    )
    for count, margin, maxiter in schedule:
        if time.time() >= end_time:
            break
        lags = active_lags(best, min(count, 2 * n - 1), margin)
        z0 = np.empty(n + 1, dtype=float)
        z0[:-1] = best
        z0[-1] = best_c + 1e-9
        cons = (
            {"type": "eq", "fun": epi_mass, "jac": epi_mass_jac, "args": (target,)},
            {"type": "ineq", "fun": epi_ineq, "jac": epi_ineq_jac, "args": (lags,)},
        )
        res = minimize(
            epi_obj, z0, args=(lags,), method="SLSQP", jac=epi_jac,
            bounds=[(0.0, 1.0)] * n + [(0.0, 1.0)],
            constraints=cons,
            options={"maxiter": maxiter, "ftol": 5e-14, "disp": False},
        )
        if hasattr(res, "x"):
            cand = capped_simplex_project(res.x[:-1], target)
            c = erdos_c5_value(cand)
            if c < best_c - 1e-14:
                best, best_c = cand, c
            else:
                break
    return best, best_c

def improve_candidate(h, end_time, seed):
    best = capped_simplex_project(h, h.size / 2.0)
    best_c = erdos_c5_value(best)

    steps = (
        ("coord", 42.0),
        ("slp1", 78.0),
        ("soft", 58.0),
        ("coord", 35.0),
        ("epi", 62.0),
        ("slp2", 68.0),
        ("soft", 45.0),
        ("epi", 9999.0),
    )

    for name, secs in steps:
        if time.time() >= end_time:
            break
        stop = min(end_time, time.time() + secs)
        if name == "coord":
            best, best_c = coordinate_descent_active(best, stop, seed + 101)
        elif name == "slp1":
            best, best_c = slp_pass(best, stop, seed + 211, 0.014, 500, 0.00155)
        elif name == "slp2":
            best, best_c = slp_pass(best, stop, seed + 307, 0.0045, 650, 0.00095)
        elif name == "soft":
            best, best_c = slsqp_soft_polish(best, stop)
        else:
            best, best_c = epigraph_polish(best, stop)

    return best, best_c

def run(seed=42, budget_s=500, **kwargs):
